"""Static files written into every test build directory."""

# Own main() instead of gtest_main: on Windows, keep crashes and CRT asserts from
# opening modal dialogs (which would hang the run until the timeout).
TEST_MAIN = """\
// Generated by MasT.
#include <gtest/gtest.h>

#ifdef _WIN32
#include <windows.h>
#include <crtdbg.h>
#include <cstdlib>
#endif

int main(int argc, char** argv) {
#ifdef _WIN32
    SetErrorMode(SEM_FAILCRITICALERRORS | SEM_NOGPFAULTERRORBOX);
    _set_abort_behavior(0, _WRITE_ABORT_MSG | _CALL_REPORTFAULT);
    _CrtSetReportMode(_CRT_ASSERT, _CRTDBG_MODE_FILE | _CRTDBG_MODE_DEBUG);
    _CrtSetReportFile(_CRT_ASSERT, _CRTDBG_FILE_STDERR);
    _CrtSetReportMode(_CRT_ERROR, _CRTDBG_MODE_FILE | _CRTDBG_MODE_DEBUG);
    _CrtSetReportFile(_CRT_ERROR, _CRTDBG_FILE_STDERR);
#endif
    ::testing::InitGoogleTest(&argc, argv);
    return RUN_ALL_TESTS();
}
"""

CMAKE_HEADER = """\
# Generated by MasT. Regenerated on every run.
cmake_minimum_required(VERSION 3.20)
project(mast_tests CXX)

set(CMAKE_CXX_STANDARD 17)
set(CMAKE_CXX_STANDARD_REQUIRED ON)
set(gtest_force_shared_crt ON CACHE BOOL "" FORCE)
set(BUILD_GMOCK OFF CACHE BOOL "" FORCE)
set(INSTALL_GTEST OFF CACHE BOOL "" FORCE)

add_subdirectory("{gtest_root}" "${{CMAKE_BINARY_DIR}}/googletest" EXCLUDE_FROM_ALL)
"""
